-- =====================================================================
-- CrowdShip — Consolidated Final Schema
-- Generated by combining: 1783842934033_schema.sql (base) + 17 migrations
-- =====================================================================
--
-- NOTES ON THINGS WORTH REVIEWING (left intact below, flagged here):
--
-- 1. Duplicate/overlapping RLS policies on public.users:
--    The base schema created "Users can view their own profile" (SELECT,
--    own row only) and "Users can update their own profile" (UPDATE, own
--    row only). fix_users_rls.sql later ADDED "Allow view access for
--    authenticated users" (SELECT, any authenticated user, any row) and
--    "Allow update for own profile" (UPDATE, own row only). Because
--    Postgres RLS policies are OR'd together, the old SELECT policy is
--    now redundant (fully subsumed by the new permissive one), and the
--    two UPDATE policies are functionally identical. Both sets are kept
--    below to faithfully reflect the true post-migration database state,
--    but you likely want to DROP the two original ones.
--
-- 2. Double-payout risk on delivery:
--    complete_delivery() (from create_otp_verification_functions.sql)
--    directly updates shipments.status = 'delivered', credits the
--    business wallet with commission, and credits the traveler's
--    wallet_balance — all inline. Separately, the base schema's
--    trigger_shipment_delivered (calling handle_shipment_delivery())
--    fires AFTER UPDATE whenever a shipment's status transitions to
--    'delivered', and ALSO credits the traveler's wallet_balance and
--    clears escrow. Calling complete_delivery() will therefore fire
--    the trigger too, potentially paying the traveler twice and
--    double-counting the commission. Left as-is below; flagging for
--    your review.
--
-- 3. match_shipments_to_route had three revisions:
--      a) base schema.sql            — SQL function, lat/lng table output
--      b) add_route_matching.sql     — plpgsql, OR (pickup OR dropoff) match
--      c) fix_route_matching_function.sql — plpgsql, AND + direction check
--    (c) DROPs the exact signature created in (b) and is the final,
--    intended version, so only (c) is included below. (a) has a
--    different signature (radius_meters float, no default) and was
--    never dropped, so technically it still coexists as an overload in
--    a real migration history — included at the end of the functions
--    section for completeness, commented out. Uncomment only if you
--    actually want both overloads.
--
-- 4. shipments.pickup_location / dropoff_location are GEOGRAPHY(Point,4326)
--    while the newly-added shipments.pickup_route is GEOMETRY(LineString,
--    4326) — a type inconsistency inherited from add_route_matching.sql.
--
-- =====================================================================


-- =====================================================================
-- EXTENSIONS
-- =====================================================================
create extension if not exists postgis;
create extension if not exists "uuid-ossp";   -- for uuid_generate_v4()
create extension if not exists pgcrypto;      -- for gen_random_uuid()
create extension if not exists pg_cron;       -- for scheduled cleanup job


-- =====================================================================
-- CUSTOM TYPES
-- =====================================================================
create type kyc_status as enum ('pending', 'approved', 'rejected');
create type shipment_status as enum ('pending', 'accepted', 'in_transit', 'delivered', 'cancelled');
create type transaction_status as enum ('held', 'released', 'refunded');


-- =====================================================================
-- TABLE: public.users
-- =====================================================================
create table public.users (
  id uuid references auth.users not null primary key,
  full_name text,
  phone_number text,
  avatar_url text,
  is_kyc_verified boolean default false,
  trust_score int default 100,
  role text check (role in ('user', 'admin')) default 'user',
  wallet_balance decimal default 0.0,
  escrow_balance decimal default 0.0,
  created_at timestamptz default now(),
  -- added by add_is_suspended.sql
  is_suspended boolean default false,
  -- added by create_ratings_table.sql
  average_rating decimal(2,1) default 0.0,
  total_ratings integer default 0
);

alter table public.users enable row level security;

-- Original policies (base schema.sql)
create policy "Users can view their own profile" on public.users
  for select using (auth.uid() = id);

create policy "Users can insert their own profile" on public.users
  for insert with check (auth.uid() = id);

create policy "Users can update their own profile" on public.users
  for update using (auth.uid() = id);

-- Added by fix_users_rls.sql (see note #1 above re: overlap)
create policy "Allow view access for authenticated users"
on public.users for select
to authenticated
using (true);

create policy "Allow update for own profile"
on public.users for update
to authenticated
using (auth.uid() = id)
with check (auth.uid() = id);


-- =====================================================================
-- TABLE: public.kyc_documents
-- =====================================================================
create table public.kyc_documents (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references public.users(id) not null,
  document_url text not null,
  status kyc_status default 'pending',
  admin_note text,
  created_at timestamptz default now(),
  -- added by add_kyc_columns.sql
  document_type text,
  document_url_back text,
  proof_of_address_url text
);

comment on column public.kyc_documents.document_type is 'Type of ID document: passport, drivers_license, or national_id';

alter table public.kyc_documents enable row level security;

-- Final policy set from fix_kyc_rls.sql (superseded the base schema's
-- two original policies, which shared the same names and were dropped
-- and recreated identically here)
create policy "Users can view their own KYC docs"
on public.kyc_documents
for select
using (auth.uid() = user_id);

create policy "Users can upload KYC docs"
on public.kyc_documents
for insert
with check (auth.uid() = user_id);

create policy "Service role can access all KYC docs"
on public.kyc_documents
for select
using (
  auth.jwt() is null
  or
  auth.jwt()->>'role' = 'service_role'
);

create policy "Service role can update KYC docs"
on public.kyc_documents
for update
using (
  auth.jwt() is null
  or
  auth.jwt()->>'role' = 'service_role'
);


-- =====================================================================
-- TABLE: public.shipments
-- =====================================================================
create table public.shipments (
  id uuid default gen_random_uuid() primary key,
  sender_id uuid references public.users(id) not null,
  traveler_id uuid references public.users(id),
  title text not null,
  description text,
  weight_kg decimal,
  image_url text,
  pickup_address text,
  pickup_location geography(Point, 4326),
  dropoff_address text,
  dropoff_location geography(Point, 4326),
  status shipment_status default 'pending',
  offer_price decimal not null,
  pickup_otp text,
  delivery_otp text,
  created_at timestamptz default now(),
  -- added by add_cancellation_fields.sql
  cancelled_at timestamptz,
  cancelled_by uuid references public.users(id),
  cancellation_penalty decimal(10,2) default 0,
  -- added by add_delivered_at_column.sql
  delivered_at timestamptz,
  -- added by add_route_matching.sql
  pickup_route geometry(LineString, 4326),
  -- added by add_shipment_images.sql
  image_urls text[]
  -- bidding_enabled, accepted_bid_id, auto_accept_initial_price are
  -- added further below via ALTER TABLE, once public.bids exists
  -- (accepted_bid_id references bids.id)
);

alter table public.shipments enable row level security;

-- Policies from base schema.sql
create policy "Anyone can view pending shipments" on public.shipments
  for select using (status = 'pending');

create policy "Sender can view their shipments" on public.shipments
  for select using (auth.uid() = sender_id);

create policy "Traveler can view assigned shipments" on public.shipments
  for select using (auth.uid() = traveler_id);

create policy "Sender can create shipments" on public.shipments
  for insert with check (auth.uid() = sender_id);

create policy "Sender can update pending shipments" on public.shipments
  for update using (auth.uid() = sender_id and status = 'pending');

create policy "Traveler can update status" on public.shipments
  for update using (auth.uid() = traveler_id);

-- Added by fix_cancellation_rls.sql (see note #1 — overlaps the two
-- policies immediately above, kept for fidelity to the migration history)
create policy "Users can update own shipments" on public.shipments
for update
using (
    auth.uid() = sender_id or auth.uid() = traveler_id
)
with check (
    auth.uid() = sender_id or auth.uid() = traveler_id
);

-- Indexes
create index if not exists idx_shipments_cancelled_at on public.shipments(cancelled_at);
create index if not exists idx_shipments_cancelled_by on public.shipments(cancelled_by);
create index if not exists idx_shipments_delivered_at
  on public.shipments(delivered_at)
  where delivered_at is not null;
create index if not exists idx_shipments_pickup_route
  on public.shipments using gist(pickup_route);


-- =====================================================================
-- TABLE: public.trips  (base schema.sql, unmodified by migrations)
-- =====================================================================
create table public.trips (
  id uuid default gen_random_uuid() primary key,
  traveler_id uuid references public.users(id) not null,
  origin_address text,
  origin_location geography(Point, 4326),
  destination_address text,
  destination_location geography(Point, 4326),
  route_polyline text,
  departure_time timestamptz,
  created_at timestamptz default now()
