alter table public.trips enable row level security;

create policy "Traveler can manage their trips" on public.trips
  for all using (auth.uid() = traveler_id);


-- =====================================================================
-- TABLE: public.transactions  (base schema.sql, unmodified by migrations)
-- =====================================================================
create table public.transactions (
  id uuid default gen_random_uuid() primary key,
  shipment_id uuid references public.shipments(id) not null,
  amount decimal not null,
  commission_fee decimal default 0.0,
  status transaction_status default 'held',
  created_at timestamptz default now()
);

alter table public.transactions enable row level security;

create policy "Users can view transactions concerning them" on public.transactions
  for select using (
    exists (
      select 1 from public.shipments s
      where s.id = shipment_id
      and (s.sender_id = auth.uid() or s.traveler_id = auth.uid())
    )
  );


-- =====================================================================
-- TABLE: public.bids  (create_bids_table.sql)
-- =====================================================================
create table if not exists public.bids (
    id uuid primary key default uuid_generate_v4(),
    shipment_id uuid not null references public.shipments(id) on delete cascade,
    traveler_id uuid not null references public.users(id) on delete cascade,
    offered_price decimal(10,2) not null check (offered_price > 0),
    status text not null check (status in ('pending', 'accepted', 'rejected', 'withdrawn')) default 'pending',
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),

    -- Ensure one active bid per traveler per shipment
    unique(shipment_id, traveler_id)
);

create index if not exists idx_bids_shipment on public.bids(shipment_id);
create index if not exists idx_bids_traveler on public.bids(traveler_id);
create index if not exists idx_bids_status on public.bids(status);
create index if not exists idx_bids_created_at on public.bids(created_at desc);

-- Bidding-related columns on shipments (deferred here since they
-- reference public.bids.id)
alter table public.shipments
ADD COLUMN IF NOT EXISTS bidding_enabled boolean default false,
ADD COLUMN IF NOT EXISTS accepted_bid_id uuid references public.bids(id),
ADD COLUMN IF NOT EXISTS auto_accept_initial_price boolean default true;

alter table public.bids enable row level security;

create policy "Travelers can create bids"
on public.bids for insert
to authenticated
with check (
    auth.uid() = traveler_id and
    exists (
        select 1 from public.shipments
        where id = shipment_id
        and status = 'pending'
        and bidding_enabled = true
        and sender_id != auth.uid()
    )
);

create policy "Travelers can view own bids"
on public.bids for select
to authenticated
using (auth.uid() = traveler_id);

create policy "Senders can view shipment bids"
on public.bids for select
to authenticated
using (
    exists (
        select 1 from public.shipments
        where id = shipment_id
        and sender_id = auth.uid()
    )
);

create policy "Travelers can update own bids"
on public.bids for update
to authenticated
using (auth.uid() = traveler_id)
with check (auth.uid() = traveler_id);

create policy "Senders can update bid status"
on public.bids for update
to authenticated
using (
    exists (
        select 1 from public.shipments
        where id = shipment_id
        and sender_id = auth.uid()
    )
);


