-- =====================================================================
-- FUNCTIONS & TRIGGERS
-- =====================================================================

-- ---------------------------------------------------------------------
-- Route matching (final version, from fix_route_matching_function.sql)
-- ---------------------------------------------------------------------
create or replace function match_shipments_to_route(
    route_geometry text,
    radius_meters integer default 5000
)
returns setof public.shipments as $$
begin
    return query
    select s.*
    from public.shipments s
    where s.status = 'pending'
    and s.traveler_id is null
    and (
        st_dwithin(
            s.pickup_location::geography,
            st_geomfromtext(route_geometry, 4326)::geography,
            radius_meters::double precision
        )
        and
        st_dwithin(
            s.dropoff_location::geography,
            st_geomfromtext(route_geometry, 4326)::geography,
            radius_meters::double precision
        )
        and
        st_linelocatepoint(
            st_geomfromtext(route_geometry, 4326),
            s.pickup_location::geometry
        ) < st_linelocatepoint(
            st_geomfromtext(route_geometry, 4326),
            s.dropoff_location::geometry
        )
    )
    order by s.created_at desc;
end;
$$ language plpgsql stable security definer;

-- ---------------------------------------------------------------------
-- Escrow logic (base schema.sql, unmodified by migrations)
-- ---------------------------------------------------------------------
create or replace function handle_shipment_acceptance()
returns trigger
language plpgsql
security definer
as $$
begin
  if new.status = 'accepted' and old.status = 'pending' then
    update public.users
    set wallet_balance = wallet_balance - new.offer_price,
        escrow_balance = escrow_balance + new.offer_price
    where id = new.sender_id;

    insert into public.transactions (shipment_id, amount, status)
    values (new.id, new.offer_price, 'held');
  end if;
  return new;
end;
$$;

create trigger trigger_shipment_accepted
after update on public.shipments
for each row execute function handle_shipment_acceptance();

create or replace function handle_shipment_delivery()
returns trigger
language plpgsql
security definer
as $$
declare
  fee decimal;
  payout decimal;
begin
  if new.status = 'delivered' and old.status <> 'delivered' then
    fee := new.offer_price * 0.10;
    payout := new.offer_price - fee;

    update public.users
    set escrow_balance = escrow_balance - new.offer_price
    where id = new.sender_id;

    update public.users
    set wallet_balance = wallet_balance + payout
    where id = new.traveler_id;

    update public.transactions
    set status = 'released', commission_fee = fee
    where shipment_id = new.id;

  end if;
  return new;
end;
$$;

create trigger trigger_shipment_delivered
after update on public.shipments
for each row execute function handle_shipment_delivery();

-- ---------------------------------------------------------------------
-- New-user sync (final version, from add_user_trigger.sql)
-- ---------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.users (id, full_name, avatar_url, role)
  values (
    new.id,
    new.raw_user_meta_data->>'full_name',
    new.raw_user_meta_data->>'avatar_url',
    'user'
  );
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- ---------------------------------------------------------------------
-- OTP verification (final versions, from create_otp_verification_functions.sql)
-- See note #2 above re: interaction with trigger_shipment_delivered
-- ---------------------------------------------------------------------
create or replace function complete_delivery(
    shipment_id uuid,
    otp_input text
)
returns boolean
language plpgsql
security definer
as $$
declare
    v_shipment record;
    v_base_amount decimal(10, 2);
    v_commission decimal(10, 2);
    v_traveler_amount decimal(10, 2);
begin
    select * into v_shipment from public.shipments where id = shipment_id;

    if v_shipment.delivery_otp = otp_input and v_shipment.status = 'in_transit' then
        v_commission := v_shipment.offer_price * 0.10;
        v_traveler_amount := v_shipment.offer_price - v_commission;

        update public.shipments
        set
            status = 'delivered',
            delivered_at = now()
        where id = shipment_id;

        update public.business_wallet
        set
            balance = balance + v_commission,
            total_earned = total_earned + v_commission,
            updated_at = now()
        where id = '00000000-0000-0000-0000-000000000001';

        insert into public.business_wallet_transactions (shipment_id, amount, type, description)
        values (shipment_id, v_commission, 'commission', 'Commission from shipment delivery');

        update public.users
        set wallet_balance = wallet_balance + v_traveler_amount
        where id = v_shipment.traveler_id;

        return true;
    else
        return false;
    end if;
end;
$$;

create or replace function complete_pickup(
    shipment_id uuid,
    otp_input text
)
returns boolean
language plpgsql
security definer
as $$
begin
    if exists (
        select 1 from public.shipments
        where id = shipment_id
        and pickup_otp = otp_input
        and status = 'accepted'
    ) then
        update public.shipments
        set status = 'in_transit'
        where id = shipment_id;

        return true;
    else
        return false;
    end if;
end;
$$;

-- ---------------------------------------------------------------------
-- Bids: auto-update updated_at (create_bids_table.sql)
-- ---------------------------------------------------------------------
create or replace function update_bids_updated_at()
returns trigger as $$
begin
    new.updated_at = now();
    return new;
end;
$$ language plpgsql;

create trigger bids_updated_at
before update on public.bids
for each row
execute function update_bids_updated_at();

-- ---------------------------------------------------------------------
-- Ratings: keep traveler stats in sync (create_ratings_table.sql)
-- ---------------------------------------------------------------------
create or replace function update_traveler_rating_stats()
returns trigger as $$
begin
  update public.users
  set
    average_rating = (select avg(rating) from public.ratings where traveler_id = new.traveler_id),
    total_ratings = (select count(*) from public.ratings where traveler_id = new.traveler_id)
  where id = new.traveler_id;

  return new;
end;
$$ language plpgsql security definer;

create trigger trigger_update_rating_stats
after insert on public.ratings
for each row
execute function update_traveler_rating_stats();

-- ---------------------------------------------------------------------
-- Email existence check (create_check_email_function.sql)
-- ---------------------------------------------------------------------
create or replace function public.check_email_exists(email_input text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
    return exists (
        select 1
        from auth.users
        where email = email_input
    );
end;
$$;

grant execute on function public.check_email_exists(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- Scheduled cleanup of unverified users (cleanup_unverified_users.sql)
-- ---------------------------------------------------------------------
create or replace function cleanup_unverified_users()
returns integer
language plpgsql
security definer
as $$
declare
    deleted_count integer;
begin
    with deleted as (
        delete from auth.users
        where created_at < now() - interval '20 minutes'
        and email_confirmed_at is null
        returning id
    )
    select count(*) into deleted_count from deleted;

    raise notice 'Cleaned up % unverified user(s)', deleted_count;

    return deleted_count;
end;
$$;

comment on function cleanup_unverified_users() is
'Deletes users who registered but never verified their email within 20 minutes. Returns count of deleted users.';

do $$
begin
    perform cron.unschedule('cleanup-unverified-users')
    where exists (select 1 from cron.job where jobname = 'cleanup-unverified-users');
exception
    when others then
        null;
end $$;

select cron.schedule(
    'cleanup-unverified-users',
    '*/5 * * * *',
    'SELECT cleanup_unverified_users();'
);


